  // Пока заглушка
  
  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <h1 className="text-3xl font-serif font-bold mb-8">Детали коллекции {id}</h1>
      {/* Добавьте контент для детальной страницы */}
    </div>
  );
};

export default CollectionDetail;
